import {advancedQuestion} from './advanced-author';
import type {SourceRow} from './source-author';

const pdfOffset=(p:number)=>p<=1368?p-1020:p<=1387?p-1036:p-1040;
const q=(n:number,row:SourceRow,score:number,reason:string,expressions:string[],related:number[]=[])=>
 advancedQuestion('nefrologie',36,pdfOffset,`nefrologie-adv-${String(n).padStart(3,'0')}`,row,[score,reason],expressions,undefined,related);

export const NEFROLOGIE_D=[
q(115,['Înainte de biopsia renală transcutanată (Cadranul 36.6) se cere:',
 ['Un bilanț de coagulare, care trebuie să fie normal','Gruparea și salvarea serului pentru cross-match, în eventualitatea unei transfuzii','O explicație completă a procedurii și obținerea consimțământului','Inițierea imediată a heparinei terapeutice, pentru a preveni tromboza de fistulă','Poziție în decubit dorsal, identică biopsiei hepatice, fără ecograf'],'ABC',1352,'Glomerulul și afectarea glomerulară — Biopsia: pregătirea pre-procedurală',
 'Aplicarea pașilor din Cadranul 36.6 care preced puncția (coagulare, cross-match, consimțământ).',
 ['Cadranul cere un bilanț de coagulare normal.','Serul este grupat și salvat pentru cross-match în caz de transfuzie.','Explicația completă și consimțământul sunt explicitate.','Heparina terapeutică ar crește riscul hemoragic, nu este un pas pre-biopsie.','Poziția este în decubit ventral, sub ghidaj ecografic, nu dorsal ca la ficat.']],
 8,'Pașii „înainte” din același cadran sunt ușor de confundat cu timpul procedural (ventral, apnee) deja consacrat.',['bilanţ de coagulare','cross-match']),

q(116,['Indicațiile biopsiei renale transcutanate, efectuate în centre de specialitate, includ:',
 ['Investigarea sindroamelor nefritice și nefrotice','Afecțiuni renale acute și cronice','Hematuria după investigații urologice și disfuncția grefei renale','Înlocuirea MAG3 ca test de primă intenție al obstrucției pielocaliceale','Diagnosticul de rutină al refluxului vezico-ureteral la copil'],'ABC',1351,'Investigații — Biopsia renală: indicații',
 'Recunoașterea spectrului de indicații (nefritic/nefrotic, acut/cronic, hematurie post-urologică, grefă).',
 ['Sindroamele nefritice și nefrotice sunt indicații citate.','Afecțiunile acute și cronice figurează explicit.','Hematuria după bilanț urologic și disfuncția de grefă sunt menționate.','Obstrucția pielocaliceală se evaluează cu MAG3, nu prin biopsie.','Refluxul la copil se studiază prin cistouretrografie.']],
 8,'Capcana mută indicațiile scintigrafiei și ale cistouretrografiei pe o biopsie de parenchim.',['sindroamelor nefritice','disfuncţiei grefei renale']),

q(117,['Pe renogramele MAG3 complete, obstrucția este sugerată când:',
 ['Curba timp-activitate nu reușește să scadă după un vârf inițial sau continuă să crească','Furosemidul poate fi administrat pentru a crește debitul urinar și a sublinia întârzierea golirii','Trasorul se leagă static de tubii proximali, ca DMSA, fără fază dinamică','Furosemidul este interzis, deoarece maschează obstrucția prin creșterea debitului','Cistouretrografia înlocuiește MAG3 la adultul cu obstrucție pielocaliceală'],'AB',1351,'Investigații — Renograma MAG3: curba și furosemidul',
 'Citirea curbei care platonează/crește și a rolului furosemidului de a demasca golirea întârziată.',
 ['Textul descrie eșecul scăderii după vârf sau creșterea continuă ca confirmare a obstrucției.','Furosemidul este dat tocmai pentru a crește debitul și a sublinia întârzierea.','Legarea de tubii proximali definește DMSA, nu MAG3 dinamic.','Furosemidul nu este interzis; este un adjuvant diagnostic.','Cistouretrografia evaluează refluxul la copil, nu obstrucția pielocaliceală a adultului.']],
 8,'Inversează rolul furosemidului (demască versus maschează) pe aceeași frază a renogramei.',['vârf iniţial','Furosemidul']),

q(118,['Identificați afirmația corectă referitoare la complicațiile biopsiei renale transcutanate (Cadranul 36.7):',
 ['Rata mortalității este de aproximativ 10%','Ocluzia angiografică sau nefrectomia pentru sângerare sunt necesare la circa 1 din 40 de pacienți','Anevrismul arteriovenos apare la aproximativ 20% dintre pacienți, fără semnificație clinică în marea majoritate a cazurilor','Hematuria macroscopică este excepțională, sub 0,1%','Anevrismul arteriovenos are, de regulă, impact hemodinamic major, impunând nefrectomie'],'C',1352,'Glomerulul și afectarea glomerulară — Cadranul 36.7: anevrismul și mortalitatea',
 'Reținerea cotei de ~20% anevrisme fără semnificație clinică și a mortalității de ~0,1%, distincte de 1/400.',
 ['Mortalitatea citată este de aproximativ 0,1%, nu 10%.','Nefrectomia/ocluzia angiografică figurează la circa 1 din 400, nu 1 din 40.','Cadranul plasează anevrismul la ~20%, aproape fără semnificație clinică.','Hematuria macroscopică ajunge până la 10%.','Textul precizează absența semnificației clinice în marea majoritate, nu impactul hemodinamic major.']],
 8,'Permutează 20% (anevrism benign), 0,1% (mortalitate) și 1 din 400 (nefrectomie), trei cifre din același cadran.',['aproximativ 20%','0,1%']),

q(119,['În descrierea bolilor glomerulare, termenii din Cadranul 36.8 mai includ:',
 ['Segmental: doar o parte a glomerulului este afectată; majoritatea leziunilor focale sunt și segmentare','Global: tot glomerulul este implicat simetric','Modificări ale membranei: îngroșarea peretelui capilar prin depozite imune sau modificări ale membranei bazale','Segmental: tot glomerulul este implicat simetric, sinonim cu „difuz”','Proliferativ: îngroșarea peretelui capilar fără nicio creștere a numărului de celule'],'ABC',1352,'Glomerulul și afectarea glomerulară — Cadranul 36.8: segmental versus membrană',
 'Deosebirea segmental/global de „modificările de membrană”, fără a le confunda cu proliferativul.',
 ['Definiția segmentală și observația că leziunile focale sunt adesea și segmentare sunt din cadran.','Global înseamnă implicarea simetrică a întregului glomerul.','Îngroșarea peretelui prin depozite sau prin modificări ale MBG definește modificările de membrană.','Implicarea simetrică a întregului glomerul este „global”, nu „segmental”.','Proliferativul înseamnă creștere a numărului de celule, nu doar îngroșare de perete.']],
 8,'Cuvintele segmental/global/membrană sunt concepute să fie permute cu „difuz” și cu proliferativul.',['doar o parte a glomerulului','Modificări ale membranei']),

q(120,['Atașarea podocitelor la membrana bazală glomerulară se face prin:',
 ['Molecule de adeziune precum α3β1 și distroglicani','Proteine ale diafragmei cu fante care includ și P-caderina, α- și β-catenina','Nefrina care înlocuiește α3β1 și leagă podocitul de MBG prin PLA2R','Distroglicanii care definesc forma secundară de GSFS prin obezitate','P-caderina care este antigenul Goodpasture, α3(IV) NC1'],'AB',1352,'Glomerulul și afectarea glomerulară — Adeziunea podocitară: α3β1 și catenine',
 'Completarea listei diafragmei (P-caderină, catenine) cu moleculele de adeziune la MBG (α3β1, distroglicani).',
 ['Textul numește α3β1 și distroglicanii ca molecule de adeziune la MBG.','P-caderina și cateninele completează lista proteinelor fantei, alături de nefrină/CD2AP.','Nefrina este proteină a fantei, nu înlocuitor al α3β1; PLA2R aparține membranoasei.','Distroglicanii nu definesc GSFS de obezitate.','Antigenul Goodpasture este α3(IV) NC1, nu P-caderina.']],
 8,'α3β1/distroglicanii (adeziune la MBG) sunt ușor de mutat pe fantă sau pe Goodpasture.',['distroglicani','P-cadherina']),

q(121,['După o insultă imună inițială, mecanismele secundare de leziune glomerulară pot include:',
 ['Depunerea de fibrină','Agregarea plachetară','Infiltrarea neutrofilelor și injuriile provocate de radicalii liberi','Absența oricărei leziuni interstițiale, afectarea fiind strict glomerulară','Implicarea unui singur rinichi, celălalt fiind cruțat sistematic'],'ABC',1352,'Glomerulul și afectarea glomerulară — Mecanisme secundare post-imune',
 'Recunoașterea cascadei fibrină–plachete–neutrofile–ROS, pe fondul leziunii interstițiale simetrice.',
 ['Depunerea de fibrină este citată ca mecanism secundar.','Agregarea plachetară figurează în aceeași listă.','Neutrofilele și radicalii liberi completează enumerarea.','Afectarea interstițială apare în mod obișnuit.','Rinichii sunt implicați simetric.']],
 8,'Lista de efecte secundare (fibrină, plachete, ROS) este ușor de înlocuit cu „doar glomerul, un singur rinichi”.',['depunerea de fibrină','radicalii liberi']),

q(122,['Precizați enunțul corect privind trăsăturile extraglomerulare ale nefritei lupice:',
 ['Nefrita tubulointerstițială apare la 75% dintre pacienți','Leziunea dominantă este PAN a arterelor medii, ANCA-pozitivă','Macroglosia și purpura periorbitală definesc forma renală','Cadranul ISN/RPS clasează NTI lupică drept clasă VI de la debut','Tromboza venoasă renală exclude diagnosticul de LES'],'A',1367,'Glomerulul și afectarea glomerulară — Nefrita lupică: NTI la 75%',
 'Reținerea cotei de 75% NTI și a spectrului trombotic (venă renală, stenoză arterială) legat de antifosfolipidici.',
 ['Textul citează nefrita tubulointerstițială la 75% dintre pacienți.','PAN ANCA-pozitivă nu este leziunea lupică extraglomerulară descrisă.','Macroglosia aparține amiloidozei AL, nu LES.','Clasa VI este glomeruloscleroza, nu NTI.','Tromboza venoasă renală figurează printre trăsăturile extraglomerulare, nu exclude LES.']],
 8,'Cota 75% NTI este contraintuitivă față de imaginea „doar glomerulară” a nefritei lupice.',['75% dintre pacienţi','tromboza venoasă']),

q(123,['În inducția nefritei lupice de tip III, IV și V sunt adevărate:',
 ['Steroizii și ciclofosfamida intravenos în doze mari sau micofenolatul de mofetil pot fi folosiți','La populația albă, ciclofosfamida în doze mici are eficacitate similară dozelor mari, cu toxicitate mai redusă','Ciclofosfamida poate fi inferioară MMF în populațiile afro-americană și hispanică, posibil prin toleranță slabă','Ciclofosfamida orală înlocuiește MMF la toți hispanicii, fiind superioară indiferent de etnie','Tipul I se induce identic, cu plasmafereză de la diagnostic'],'ABC',1367,'Glomerulul și afectarea glomerulară — Nefrita lupică: inducție și etnie',
 'Nuanțarea inducției (CYC vs MMF) după etnie, cu alternativa dozelor mici la albi.',
 ['Cele două linii de inducție (CYC i.v. doze mari sau MMF) sunt din text.','Dozele mici de CYC la albi au eficacitate similară și toxicitate mai mică.','Inferioritatea posibilă a CYC față de MMF la afro-americani/hispanici este explicită.','Textul nu inversează ierarhia în favoarea CYC la hispanici.','Tipul I nu necesită tratament specific.']],
 8,'Etnia (alb vs afro-american/hispanic) permută CYC și MMF; distractorul tratează clasa I ca GNRP.',['populaţia albă','a/ro-americană']),

q(124,['Menținerea remisiunii în nefrita lupică și locul rituximabului:',
 ['MMF este superior azatioprinei în terapia de menținere','Azatioprina are eficacitate similară ciclosporinei în reducerea riscului de recidivă','Rituximabul a arătat rezultate favorabile pe termen scurt la unii pacienți, dar trialurile randomizate nu au fost consistente','Rituximabul poate fi util în nefritele lupice refractare severe','Azatioprina este superioară MMF, iar rituximabul înlocuiește inducția la clasa I'],'ABCD',1367,'Glomerulul și afectarea glomerulară — Nefrita lupică: menținere și rituximab',
 'Ierarhizarea MMF > AZA ≈ ciclosporină la menținere și rezervarea rituximabului pentru formele refractare.',
 ['Superioritatea MMF față de azatioprină este citată.','Azatioprina și ciclosporina sunt similare pentru prevenția recidivei.','Inconsistența RCT-urilor de rituximab este explicită.','Utilitatea în formele refractare severe este menționată.','Ierarhia este inversă; clasa I nu se induce cu rituximab.']],
 8,'Capcana este „overtreatment” al clasei I și inversarea MMF versus azatioprină.',['superior azatioprinei','nefritele lu pice refractare']),

q(125,['Crioglobulinemiile, după tipul imunoglobulinic, se caracterizează prin:',
 ['Tipul I: crioprecipitarea unui singur tip monoclonal, întâlnit în mielom și alte boli limfoproliferative','Tipul II: antiglobuline IgM monoclonale cu activitate de factor reumatoid, adesea cu VHC','Tipurile II reprezintă 40–60%, iar tipul III 40–50% din cazuri; afectarea glomerulară este mai frecventă în tipul II','Tipul III are antiglobuline IgM monoclonale, identic mielomului, fără VHC','Toate tipurile sunt ANCA-PR3 pozitive, cu semilune pauci-imune'],'ABC',1367,'Glomerulul și afectarea glomerulară — Crioglobuline: tipurile I–III',
 'Maparea tip I monoclonal / tip II IgM-RF+VHC / cotele 40–60% versus 40–50%, cu predilecție glomerulară pentru tipul II.',
 ['Tipul I monoclonal din mielom/limfoproliferări este din text.','Tipul II cu IgM monoclonal RF și VHC este explicit.','Cotele și predilecția glomerulară a tipului II sunt citate.','Tipul III are IgM policlonale, nu monoclonale de mielom.','Nu sunt vasculite ANCA pauci-imune.']],
 8,'Cotele 40–60%/40–50% și monoclonal versus policlonal sunt ușor de permutat cu mielomul sau ANCA.',['40-60%','factor reumatoid']),

q(126,['Boala renală crioglobulinemică, dincolo de clasificarea tipurilor:',
 ['Devine clinic manifestă în a patra sau a cincea decadă, femeile fiind mai frecvent afectate','Caracteristicile sistemice includ purpura, artralgiile, ulcerele de picior, Raynaud, polineuropatie și afectare hepatică','Terapia cu antivirale cu acțiune directă este extrem de eficientă când cauza este VHC','Plasmafereza intensivă sau criofiltrarea au fost folosite în vasculita cu risc vital','Predomină la bărbații adolescenți, DAA fiind inutile, unica linie fiind nefrectomia'],'ABCD',1367,'Glomerulul și afectarea glomerulară — Crioglobulinemia: clinic și DAA',
 'Corelarea vârstei/sexului, a purpurei și a DAA/plasmaferezei, distincte de o „vasculită chirurgicală”.',
 ['Decada a 4-a/5-a și predominanța feminină sunt din text.','Lista sistemică (purpură, Raynaud, hepatită) este explicită.','DAA sunt extrem de eficiente în VHC.','Plasmafereza/criofiltrarea sunt rezervate formelor cu risc vital.','Nu predomină la adolescenți și nu se tratează prin nefrectomie.']],
 8,'Plasmafereza de urgență este ușor de înlocuit cu nefrectomia din xantogranulomatoasă; DAA sunt detaliul etiologic.',['a patra sau a cincea','criofiltra']),

q(127,['Vasculita cu imunoglobulină A (sindromul Henoch–Schönlein):',
 ['Cuprinde erupția cutanată caracteristică, colici abdominale, dureri articulare și glomerulonefrită','Aproximativ 30–70% dintre pacienți au hematurie și/sau proteinurie','Leziunea este o GN proliferativă focală segmentară cu hipercelularitate mezangială; depozitele sunt în principal IgA mezangiale','Nu există tratament cu eficiență dovedită; steroizii sunt ineficienți, îngrijirea fiind de obicei suportivă','Este identică PAN, ANCA-pozitivă, cu anevrisme de artere medii și nefrectomie de elecție'],'ABCD',1367,'Glomerulul și afectarea glomerulară — Purpura Henoch–Schönlein',
 'Recunoașterea tetradei clinică, a cotei 30–70% și a caracterului suportiv (steroizi ineficienți).',
 ['Tetrada cutanat–abdominal–articular–renal este din text.','Cota 30-70% este explicită.','Histologia și depozitele de IgA mezangiale sunt descrise.','Absența unui tratament dovedit și ineficiența steroizilor sunt citate.','Nu este PAN ANCA; nefrectomia aparține altei entități.']],
 8,'Ineficiența steroizilor este contraintuitivă într-o vasculită IgA; distractorul mută PAN/nefrectomia.',['30-70%','cu steroizi']),

q(128,['Un bărbat tânăr cu angiokeratoame, proteinurie progresivă și neuropatie este evaluat pentru boala Fabry. Sunt adevărate:',
 ['Este o boală de stocare lizozomală legată de X, prin deficit de α-galactozidază','Se acumulează glicosfingolipide (globotriaozilceramide) în podocite','Tabloul include angiokeratoame, afectare cardiovasculară, neuropatii și BCR cu proteinurie progresivă','Agalsidaza încetinește progresia leziunilor cardiace, renale și cutanate; migalastatul oral poate fi eficient în cazuri selectate','Transmiterea este autozomal recesivă prin PKHD1, identică bolii polichistice infantile'],'ABCD',1367,'Glomerulul și afectarea glomerulară — Boala Fabry: agalsidază și migalastat',
 'Legarea deficitului de α-galactozidază de angiokeratoame și de cele două linii (agalsidază, migalastat).',
 ['Transmiterea X-linkată și enzima sunt din text.','Globotriaozilceramidele în podocite sunt explicitate.','Tabloul cutanat-cardio-neuro-renal este listat.','Agalsidaza și migalastatul (chaperonă orală) sunt citate.','PKHD1 aparține BPR recesive, nu Fabry.']],
 8,'Vigneta cutanată împinge spre vasculită; chaperona orală migalastat este detaliul ușor de omis.',['agalsidază','miga']),

q(129,['Nefropatia asociată anemiei falciforme, dincolo de leziunea glomerulară APOL1:',
 ['Se complică frecvent cu scleroză sau necroză papilară','Poate asocia diabet insipid nefrogen','Poate asocia acidoză tubulară renală incompletă','GN membranoasă sau mezangiocapilară cu depozite de IgG poate apărea ocazional, fără infecție prealabilă','Leziunea dominantă este boala anti-MBG, cu semilune la toți homozigoții SS'],'ABCD',1367,'Implicarea rinichiului în alte afecțiuni — Siclemia: papilă, DIN și ATR',
 'Completarea necrozei papilare, a diabetului insipid nefrogen și a ATR incomplete, plus GN membranoasă/MCGN ocazională.',
 ['Scleroza sau necroza papilară sunt frecvente.','Diabetul insipid nefrogen este citat.','ATR incompletă figurează în aceeași frază.','Membranoasa/MCGN cu IgG, fără infecție prealabilă, este menționată pe pagina următoare.','Nu este boală anti-MBG.']],
 8,'Triada papilă–DIN–ATR este ușor de înlocuit cu un pattern glomerular anti-MBG.',['diabet insipid nefrogen','acidoză tubulară'],[1368]),

q(130,['Criza renală sclerodermică, dincolo de prevalența de ~10%:',
 ['La biopsie, arterele arcuate și interlobulare au aspect „în foițe de ceapă” prin proliferare intimală, trombi de fibrină și necroză fibrinoidă','Inhibitorii ECA sunt tratamentul de elecție și au ameliorat semnificativ prognosticul','Mortalitatea prin insuficiență renală este azi rară, deși sub 30% progresează spre BRT','CXCL4 produs de dendriticele plasmocitoide se asociază cu fibroză tegumentară, pulmonară și hipertensiune pulmonară','Leziunea este o GNRP ANCA-pozitivă, IECA fiind contraindicați'],'ABCD',1368,'Implicarea rinichiului în alte afecțiuni — SSc: foițe de ceapă și IECA',
 'Recunoașterea histologiei „foițe de ceapă”, a elecției IECA și a cotei <30% către BRT.',
 ['Aspectul în foițe de ceapă cu trombi și necroză fibrinoidă este din text.','IECA sunt tratamentul de elecție.','Mortalitatea renală este rară; <30% ajung la BRT.','CXCL4 și asocierile fibrotic-pulmonare sunt citate.','Nu este o vasculită ANCA; IECA nu sunt contraindicați.']],
 8,'IECA ca elecție este contraintuitiv față de o „criză hipertensivă”; distractorul o tratează ca GPA.',['foiţe de ceapă','sub 30%']),

q(131,['Un copil dezvoltă oligurie și trombocitopenie la o săptămână după o gastroenterită febrilă. Referitor la SHU sunt adevărate:',
 ['Asociază hemoliză intravasculară cu fragmentări eritrocitare, trombocitopenie și AKI prin tromboze de artere mici și arteriole','Testele de coagulare sunt de regulă normale, spre deosebire de CID','SHU+D urmează adesea gastroenteritei cu E. coli O157, care produce verotoxină (toxină Shiga)','Unitatea patogenică A a verotoxinei inhibă sinteza proteică','SHU este o vasculită ANCA-PR3, cu coagulare consumptivă identică CID'],'ABCD',1368,'Implicarea rinichiului în alte afecțiuni — SHU+D: O157 și verotoxină',
 'Deosebirea SHU (coagulare normală, O157/verotoxină) de CID și de vasculita ANCA.',
 ['Triada MAHA–trombocitopenie–AKI este din text.','Coagularea normală deosebește SHU de CID.','E. coli O157 și verotoxina/Shiga sunt explicitate.','Subunitatea A inhibă sinteza proteică.','Nu este ANCA; coagularea nu este de tip CID.']],
 8,'Vigneta post-diarreee cere O157/verotoxină; distractorul o mută pe ANCA sau CID.',['tulpina 0157','verotoxina']),

q(132,['Tuberculoza tractului urinar, dincolo de granulomul cazeos și de controlul la 2–3 luni:',
 ['Se prezintă cu poliurie, disurie sau hematurie; leziunile corticale urmează diseminării hematogene din faza primară','Infecția persistentă diseminează papilar, cu cavități și eliminare de micobacterii; pot urma stricturi ureterale și vezică contractată','Diagnosticul trebuie luat în calcul la piuria sterilă; culturile din urina de dimineață nu sunt înalt sugestive','Tratamentul este similar tuberculozei pulmonare; la bărbat poate debuta ca disconfort testicular sau epididimar','Imagistica este patognomonică în toate cazurile, culturile matinale înlocuind biopsia în TB interstițială difuză'],'ABCD',1385,'Nefritele tubulointerstițiale — Tuberculoza urinară: vezică contractată și piurie sterilă',
 'Completarea căii hematogene–papilă–vezică contractată și a slabei valori a culturilor matinale.',
 ['Prezentarea și originea hematogenă corticală sunt din text.','Cavitățile papilare, stricturile și vezica contractată sunt descrise.','Piuria sterilă și limita culturilor matinale sunt explicite.','Tratamentul este cel al TB pulmonare; debutul genital masculin este citat.','Imagistica poate fi normală în TB interstițială difuză, diagnosticul fiind bioptic.']],
 8,'Vezica contractată și slaba valoare a uroculturilor matinale sunt detalii ușor de înlocuit cu „imagistică patognomonică”.',['piurie sterilă','vezici contractate']),

q(133,['Abcesul renal hematogen stafilococic se caracterizează prin:',
 ['Urină fără anomalii, abcesul necomunicând cu bazinetul, cu extensie perirenală frecventă','Tratament cu flucloxacilină și drenaj chirurgical','Piurie masivă comunicantă, tratată doar oral 3 zile ca o cistită','Nefrectomie de elecție, identică pielonefritei xantogranulomatoase','Absența septicemiei, diagnosticul fiind pus doar prin MAG3, fără eco sau CT'],'AB',1385,'Nefritele tubulointerstițiale — Abcesul stafilococic: flucloxacilină',
 'Reținerea urinei „normale” (necomunicant) și a perechii flucloxacilină plus drenaj.',
 ['Urina fără anomalii și extensia perirenală sunt din text.','Flucloxacilina și drenajul chirurgical sunt explicitate.','Nu comunică cu bazinetul; nu este o cistită scurtă.','Nefrectomia de elecție aparține xantogranulomatoasei.','Septicemia stafilococică este de regulă prezentă; diagnosticul este eco/CT.']],
 8,'Flucloxacilina plus drenaj este ușor de înlocuit cu nefrectomia xantogranulomatoasei sau cu o cură scurtă de cistită.',['flucloxacilina','drenaj chirurgical']),

q(134,['Nefrita tubulointerstițială cronică și necroza papilară, imagistic:',
 ['Necroza papilară este bilaterală și arată „semnul inelului” (papila necrozată), fără pierdere de țesut cortical','Nefropatia de reflux poate fi unilaterală, cu calice boante, cel mai adesea la polii renali','Cauzele de necroză papilară includ consumul cronic de analgezice, diabetul zaharat și siclemia','Leziunile tubilor medulari duc la defect de concentrare și pierdere urinară de sodiu','Necroza papilară este strict unilaterală, semnul inelului definind refluxul, nu papila'],'ABCD',1386,'Nefritele tubulointerstițiale — Papila versus reflux: semnul inelului',
 'Contrastul bilateral/inel/fără pierdere corticală (papilă) versus unilateral/calice boante polare (reflux).',
 ['Bilateralitatea, semnul inelului și absența pierderii corticale sunt din cadran/figură.','Refluxul poate fi unilateral, cu calice boante polare.','Analgezicele, diabetul și siclemia sunt cauzele citate de necroză papilară.','Defectul de concentrare și natriureza sunt consecințe medulare.','Relația este inversă: papila este bilaterală; inelul este al papilei, nu al refluxului.']],
 8,'Semnul inelului versus calicele boante sunt concepute să fie permute între papilă și reflux.',['Semnul inelului','Calice boante']),

q(135,['Precizați enunțul corect privind cauzele toxice de NTI cronică din Cadranul 36.28:',
 ['Sunt implicate doar penicilinele, restul metalelor fiind inerte','Cauza dominantă este Hantavirusul, metalele nefigurând','Iradierea nu apare, fiind rezervată glomerulopatiilor cu semilune','Printre medicamente și toxice figurează ciclosporina, 5-aminosalicilații, cadmiul, plumbul, titaniul și iradierea','Cadmiul și plumbul protejează interstițiul, fiind folosiți ca chelatori de fosfat'],'D',1386,'Nefritele tubulointerstițiale — Cadranul 36.28: metale și 5-ASA',
 'Recunoașterea listei ciclosporină/5-ASA/cadmiu/plumb/titan/iradiere, distinctă de NTI acută medicamentoasă.',
 ['Penicilinele definesc NTI acută, nu lista cronică de metale.','Hantavirusul este cauză de NTI acută infecțioasă, nu metalul dominant.','Iradierea figurează în cadran.','Lista de medicamente/toxice include ciclosporina, 5-ASA, cadmiu, plumb, titan și iradiere.','Cadmiul și plumbul sunt nefrotoxice, nu chelatori protectori.']],
 8,'Metalele (cadmiu, plumb, titan) sunt detalii nefolosite, ușor de înlocuit cu penicilinele NTI acute.',['Cadmiu, plumb','5-aminosalicilati']),

q(136,['Leziunile tubilor din zonele medulare, în NTI cronice, determină:',
 ['Defecte în capacitatea de concentrare a urinii','Conservare defectuoasă a sodiului, cu poliurie și pierdere urinară de sodiu','Extinderea ulterioară a fibrozei la corticală, cu progresie a BCR','Hiperconcentrare maximală, cu oligurie și retenție de sodiu ca în SHU','Vindecare spontană universală, fără nicio progresie corticală'],'ABC',1386,'Nefritele tubulointerstițiale — NTI cronică: concentrare și natriureză',
 'Legarea leziunii medulare de isostenurie/natriureză și de fibroza corticală tardivă.',
 ['Defectul de concentrare este explicit.','Pierderea de sodiu cu poliurie este citată.','Fibroza se extinde cortical, cu progresie a BCR.','Direcția este inversă: nu hiperconcentrare/retenție.','Cauza adesea nu se identifică; progresia este descrisă.']],
 8,'Inversează natriureza medulară (pierdere de sare) cu retenția din SHU.',['capacitatea de concentrare','pierdere urinară de sodiu']),

q(137,['Identificați afirmația corectă referitoare la definiția insuficienței renale acute din text:',
 ['Este o deteriorare lentă, peste 3 luni, identică BCR','Este o deteriorare bruscă a funcției renale, de obicei în ore sau zile, de regulă reversibilă în zile–săptămâni','Impune biopsie de urgență la toți, înaintea oricărei evaluări pre-/post-renale','Ureea și creatinina sunt predictori infailibili, Cadranul 36.29 fiind abandonat','Reversibilitatea este exclusă, evoluția fiind identică stadiului G5'],'B',1387,'Insuficiența renală acută — Definiție: ore–zile, reversibilitate',
 'Fixarea ferestrei ore–zile și a reversibilității uzuale în zile–săptămâni, distinctă de pragul >3 luni al BCR.',
 ['Pragul >3 luni definește BCR, nu IRA.','Textul definește IRA ca deteriorare bruscă în ore sau zile, de obicei reversibilă.','Clasificarea pre-/parenchim-/post-renală precede biopsia.','Ureea și creatinina sunt uneori predictori suboptimali (Cadranul 36.29).','Reversibilitatea este regula, nu excepția.']],
 8,'Fereastra ore–zile versus >3 luni (BCR) este capcana de stadializare a aceleiași pagini de tranziție.',['ore sau zile','zile-săptămâni']),

q(138,['IRA, după sediul leziunii, poate fi:',
 ['Pre-renală, prin perfuzie deficitară care reduce RFG','Reno-parenchimatoasă, prin leziuni glomerulare, tubulare sau vasculare','Post-renală, prin obstrucție: rinichii sunt funcționali, dar nu pot excreta, iar presiunea retrogradă afectează funcția','Strict glomerulară, cauzele pre- și post-renale fiind eliminate din clasificare','Identică BCR stadiul G2, fără nicio componentă obstructivă'],'ABC',1387,'Insuficiența renală acută — Clasificarea pre-/intra-/post-renală',
 'Aplicarea triadei perfuzie–parenchim–obstrucție, cu presiunea retrogradă ca mecanism post-renal.',
 ['Definiția pre-renală este din text.','Compartimentul parenchimatos (glomerul, tub, vas) este explicit.','Obstrucția cu presiune retrogradă definește post-renalul.','Cele trei compartimente coexistă în clasificare.','IRA nu este echivalentul G2.']],
 8,'Presiunea retrogradă post-renală este detaliul mecanic ușor de omis în favoarea unui „doar glomerular”.',['pre-renale','post-renale']),

q(139,['La insuficiența renală inexplicabilă cu rinichi de dimensiuni normale se indică biopsie pentru a exclude:',
 ['Forme de NTI tratabile, cum ar fi NTI granulomatoasă din sarcoidoza renală, care poate fi prima manifestare a bolii','Nefropatia hiperuricemică cronică ca entitate incontestabilă, cu indicație de rasburicază la toți','NTI granulomatoasă de sarcoidoză, care poate fi revelatoare; corticosteroizii dau răspuns rapid în majoritatea cazurilor','Boala anti-MBG, unica NTI a rinichiului de dimensiuni normale','Obstrucția post-renală, biopsia înlocuind ecografia'],'AC',1387,'Nefritele tubulointerstițiale — Biopsia rinichiului „normal” și sarcoidoza',
 'Indicarea biopsiei pentru NTI granulomatoasă tratabilă (sarcoid) când rinichii sunt încă normali dimensional.',
 ['Textul cere biopsie tocmai pentru a exclude NTI tratabile, exemplul fiind sarcoidoza.','Nefropatia hiperuricemică cronică este numită entitate controversată, nu indicație de rasburicază universală.','Sarcoidoza renală poate fi prima manifestare; răspunsul la steroizi este rapid.','Anti-MBG este o glomerulopatie, nu prototipul NTI.','Obstrucția se evaluează imagistic, nu prin biopsie de primă intenție.']],
 8,'Rinichiul de dimensiuni normale într-o IRA „inexplicabilă” cere sarcoid granulomatos, nu Goodpasture.',['rinichi de dimensiuni normale','sarcoidoza renală']),

q(140,['Sindromul de liză tumorală, pe pagina de IRA, se caracterizează prin:',
 ['Eliberare de acid uric, potasiu și fosfor după liza rapidă, inclusiv sub corticosteroizi','Acidul uric seric poate atinge de 4–5 ori valoarea normală, cu uropatie prin cristale','Riscul major este hiperpotasemia; hidratarea profilactică menține diureza pentru eliminarea potasiului','Rasburicaza oxidează acidul uric la alantoină; nivelurile pot deveni nedetectabile după administrare','Rasburicaza este inutilă, riscul major fiind hipokaliemia, fără nicio uropatie cristalină'],'ABCD',1392,'Boala cronică de rinichi — Liză tumorală: alantoină și hiper-K+',
 'Ierarhizarea hiper-K+ ca risc major și a rasburicazei care face uratul nedetectabil via alantoină.',
 ['Produsele eliberate (urat, K, P) sunt din text.','Multiplicarea 4-5× și uropatia cristalină sunt explicite.','Hiperpotasemia este riscul major.','Conversia la alantoină și uratul nedetectabil sunt citate.','Direcția este inversă: rasburicaza este utilă, riscul este hiper-K+.']],
 8,'Alantoina și uratul nedetectabil sunt detalii de enzimologie ușor de înlocuit cu „hipo-K+ benign”.',['alantoina','4-5 ori']),

q(141,['Sindromul hepato-renal, în capitolul de IRA, se distinge prin:',
 ['Vasoconstricție renală importantă, cu rinichi histologic normali','Apariție doar în bolile hepatice complicate cu hipertensiune portală și ascită','Pacienții nu sunt hipovolemici; recuperarea renală este observată de obicei după transplant hepatic reușit','Este o necroză tubulară acută hipovolemică, fără legătură cu hipertensiunea portală','Spironolactona în doze crescânde este tratamentul de primă intenție, transplantul fiind inutil'],'ABC',1392,'Boala cronică de rinichi — HRS: vasoconstricție și transplant hepatic',
 'Recunoașterea caracterului funcțional (vasoconstricție, histologie normală, euvolemie) și a recuperării post-transplant hepatic.',
 ['Vasoconstricția cu histologie normală este din text.','Condiția portală+ascită este explicită.','Absența hipovolemiei și recuperarea după transplant hepatic sunt citate.','Nu este NTA hipovolemică.','Diureticele excesive precipită HRS; transplantul hepatic este soluția.']],
 8,'Euvolemia (nu hipovolemia) și recuperarea după grefă hepatică deosebesc HRS de NTA.',['vasconstricţia renală','transplant hepatic']),

q(142,['Precizați enunțul corect privind hidratarea peri-contrast la pacienții cu risc mare, cateterizați cardiac:',
 ['Dializa profilactică rămâne standardul, hidratarea fiind abandonată','N-acetilcisteina înlocuiește protocolul de lichide peri-procedural','Un trial arată că administrarea de lichide ghidată de presiunea telediastolică este sigură și mai eficientă în prevenția IRA post-contrast','Dopamina în doze „renale” este superioară protocolului de lichide','Teofilina (antagonist de adenozină) se asociază de rutină bicarbonatului, ca măsură dovedit superioară'],'C',1392,'Boala cronică de rinichi — Contrast: lichide ghidate de telediastolică',
 'Recunoașterea protocolului ghidat de presiunea telediastolică ca superior hidratării oarbe la cateterizarea cu risc.',
 ['Dializa profilactică nu este benefică.','NAC are cel mult beneficiu marginal, nu înlocuiește lichidele.','Textul citează trialul cu lichide în funcție de presiunea telediastolică.','Dopamina nu este benefică.','Teofilina nu este benefică; nu se asociază de rutină bicarbonatului.']],
 8,'Telediastolica ca ghid de lichide este detaliul de terapie intensivă nefolosit al paginii de contrast.',['telediastolică','cateterizaţi cardiac']),

q(143,['Prevalența BCR stadiul 3, conform Cadranului 36.36, crește cu vârsta astfel:',
 ['1,4% sub 65 de ani, 15,4% la 65–74 de ani, 29,4% la 75–84 de ani și 30,9% la ≥85 de ani','Totalul (stadiile 3–5) ajunge la 33,4% la ≥85 de ani, față de 1,5% sub 65 de ani','Stadiul 5 depășește 30% sub 65 de ani, stadiul 3 fiind rar la vârstnici','Prevalența stadiului 3 scade după 75 de ani, fiind maximă la tineri','Stadiul 4 are prevalență identică stadiului 3 la toate vârstele, circa 30%'],'AB',1393,'Boala cronică de rinichi — Cadranul 36.36: stadiul 3 după vârstă',
 'Memorarea saltului de prevalență a stadiului 3 de la 1,4% (<65) la ~31% (≥85).',
 ['Cifrele pe grupe de vârstă pentru stadiul 3 sunt din cadran.','Totalul 33,4% la ≥85 versus 1,5% sub 65 este explicit.','Stadiul 5 rămâne rar (0,03–0,2%); stadiul 3 domină la vârstnici.','Prevalența stadiului 3 crește, nu scade, cu vârsta.','Stadiul 4 este de ordinul 0,04–2,4%, nu 30%.']],
 8,'Permutează 1,4% și 30,9% între tineri și foarte vârstnici, capcana de ordin de mărime a cadranului.',['1,4','30,9']),

q(144,['Căile comune de progresie a BCR, independent de cauză, includ:',
 ['Fiecare rinichi are aproximativ un milion de nefroni; sarcina de filtrare se răsfrânge asupra celor rămași','Nefronii rămași sunt supuși hiperfiltrării, cu hipertrofie glomerulară și reducerea rezistenței arteriolare','Angiotensina II vasoconstrictează arteriolele postglomerulare și stimulează TGF-β și PAI-1','Prognosticul se corelează cu HTA, proteinurie și leziunea interstițială, nu cu modificările glomerulare obiectivate','Progresia este mai rapidă în NTI cronice decât în glomerulopatii, Ang II dilată arteriola eferentă'],'ABCD',1393,'Boala cronică de rinichi — Hiperfiltrare, Ang II, TGF-β și PAI-1',
 'Legarea milionului de nefroni de hiperfiltrare, de vasoconstricția eferentă și de markerii de prognostic (interstițiu > glomerul).',
 ['Milionul de nefroni și redistribuirea sarcinii sunt din text.','Hiperfiltrarea, hipertrofia și scăderea rezistenței arteriolare sunt explicite.','Vasoconstricția postglomerulară, TGF-β și PAI-1 sunt citate.','Prognosticul ține de HTA, proteinurie și interstițiu, nu de glomeruli.','Glomerulopatiile cronice se deteriorează mai rapid decât NTI; Ang II vasoconstrictează, nu dilată, eferenta.']],
 8,'Direcția Ang II (eferentă) și ierarhia interstițiu versus glomerul sunt capcanele de progresie.',['un million de nefroni','PAl-1']),

q(145,['Prognosticul BCR, independent de etiologia de fond, se corelează cu:',
 ['Hipertensiunea arterială, mai ales dacă este slab controlată','Proteinuria','Gradul de lezare histologică a interstițiului, dar nu cu modificările obiectivate în glomeruli','Glomerulopatiile cronice tind să se deterioreze mai rapid decât nefropatiile tubulointerstițiale cronice','Leziunea glomerulară izolată, fără proteinurie și fără HTA, este singurul predictor validat'],'ABCD',1393,'Boala cronică de rinichi — Predictori: interstițiu, nu glomerul',
 'Ierarhizarea HTA–proteinurie–interstițiu față de histologia glomerulară, plus viteza mai mare a glomerulopatiilor.',
 ['HTA slab controlată este primul predictor citat.','Proteinuria figurează explicit.','Interstițiul, nu glomerulul, corelează cu prognosticul.','Glomerulopatiile cronice progresează mai rapid decât NTI.','Textul neagă tocmai centralitatea leziunii glomerulare izolate.']],
 8,'Afirmația „interstițiul, nu glomerulul” este contraintuitivă într-un capitol de boli glomerulare.',['lezare histologică a interstiţiului','glomerulopatii cronice']),

q(146,['Anemia normocromă, normocitară a BCR recunoaște, pe lângă deficitul de eritropoietină, și:',
 ['Pierderi oculte digestive, prelevări repetate, pierderi pe hemodializă sau disfuncție plachetară','Afectarea măduvei prin toxine uremice sau fibroza hiperparatiroidismului','Deficit de fier, B12 sau folat; durată de viață scăzută a hematiilor în mediu uremic','IECA, care pot interfera cu eliberarea endogenă de eritropoietină','IECA stimulează EPO, anemia fiind doar feriprivă, fără hemoliză de dializă'],'ABCD',1394,'Boala cronică de rinichi — Anemia: mecanisme dincolo de EPO',
 'Completarea mecanismului principal (EPO) cu pierderi, fibroză HPT, vitamine și interferența IECA.',
 ['Lista de pierderi de sânge este din text.','Toxinele și fibroza HPT sunt citate.','Deficitele hematinice și scurtarea vieții eritrocitare figurează.','IECA pot contribui prin interferența cu EPO endogen.','Direcția IECA este inversă; hemoliza de dializă este menționată.']],
 8,'Interferența IECA cu EPO endogen este detaliul farmacologic ușor de inversat.',['Inhibitorii enzimei de conversie','viaţă scăzută']),

q(147,['După inițierea ASE, dincolo de HTA la 30% și de ținta Hb 100–120 g/L:',
 ['Rezistența periferică crește la toți pacienții, prin pierderea vasodilatației hipoxice și prin creșterea vâscozității','Complicații rare includ encefalopatia, orbirea corticală tranzitorie și hipertensiunea','Un trial a arătat că doze mari de fier i.v., cu feritină țintă în jur de 400 µg/L, sunt sigure și scad necesarul de ASE','Peptidul sintetic agonist al receptorului EPO a fost retras din cauza reacțiilor anafilactice','Rezistența periferică scade la toți, feritina țintă de 400 µg/L fiind contraindicată'],'ABCD',1394,'Boala cronică de rinichi — ASE: vâscozitate, feritină 400 și anafilaxie',
 'Legarea creșterii universale a rezistenței periferice de ținta de feritină ~400 µg/L și de retragerea peptidului anafilactic.',
 ['Creșterea rezistenței la toți, cu cele două mecanisme, este explicită.','Encefalopatia și orbirea corticală tranzitorie sunt citate ca rare.','Trialul cu feritină ~400 µg/L este din text.','Retragerea agonistului peptidic pentru anafilaxie este menționată.','Rezistența crește, nu scade; feritina ~400 a fost asociată cu siguranță.']],
 8,'Feritina 400 µg/L (trial de fier i.v.) este ușor de confudat cu pragul >500 al deficitului funcțional.',['400 µg/L','orbirea corticală']),

q(148,['Aspectele radiologice și entitățile TMO-BCR, dincolo de FGF23, includ:',
 ['Eroziuni subperiostale la degete și craniu „piperniță – pepperpot” în hiperparatiroidismul secundar','Aspect de „tricou de rugby – rugger jersey” prin osteoscleroză vertebrală în HPT persistent','Hiperparatiroidismul terțiar: PTH independent de calciu/1,25-(OH)2D3, cu hipercalcemie','Boala osoasă adinamică: turnover scăzut, FA normală, PTH scăzut; niciun tratament nu s-a dovedit eficient','Pepperpot-ul definește osteomalacia, iar tricoul de rugby este patognomonic deficitului de aluminiu'],'ABCD',1395,'Boala cronică de rinichi — TMO-BCR: pepperpot, rugger jersey, adinamică',
 'Maparea celor două semne radiologice și deosebirea HPT terțiar de osul adinamic netratabil.',
 ['Eroziunile și pepperpot-ul sunt din text.','Rugger jersey prin osteoscleroză vertebrală este explicit.','Autonomia PTH cu hipercalcemie definește terțiarul.','Osul adinamic are FA normală/PTH scăzut, fără tratament eficient.','Pepperpot-ul este al HPT, tricoul de rugby al osteosclerozei, nu al aluminiului ca semn patognomonic.']],
 8,'Permutează pepperpot, rugger jersey și osul adinamic, trei imagini din aceeași figură.',['pepperpot','tricou de rugby']),

q(149,['La pacientul dializat, valoarea PTH urmărită pentru a evita osul adinamic este:',
 ['Sub limita inferioară a normalului, identică post-paratiroidectomie','De 2–3 ori limita superioară a normalului','De zece ori normalul, ca în HPT terțiar netratat','Identică populației generale, fără nicio toleranță de supresie','Nedetectabilă, analog analogilor de vitamină D în exces'],'B',1395,'Boala cronică de rinichi — Ținta PTH 2–3× ULN la dializat',
 'Reținerea ferestrei 2–3× ULN, aleasă tocmai pentru a păstra un turnover care evită osul adinamic.',
 ['PTH subnormal definește riscul de os adinamic, nu ținta.','Textul cere PTH de 2-3 ori limita superioară la dializați.','Zece ori normalul nu este ținta.','Populația generală nu este referința la dializat.','PTH nedetectabil este nedorit.']],
 8,'Fereastra 2–3× ULN este ușor de confundat cu „normalizarea completă” care produce os adinamic.',['2-3 ori','boala osoasă adinamică']),

q(150,['Arteriolopatia calcificantă uremică (calcifilaxia) se manifestă prin:',
 ['Pete dureroase, plăgi sau ulcere, escare care nu se vindecă, paniculite și necroză dermică','Histologie: calcificări vasculare suprapuse cu tromboze de vase mici','Tiosulfatul de sodiu (antioxidant) și bifosfonații au fost încercați cu succes variabil','Mulți pacienți decedează în decurs de un an de la diagnostic, infecțiile crescând riscul','Warfarina protejează prin activarea proteinei matrix Gla, mortalitatea fiind excepțională'],'ABCD',1396,'Boala cronică de rinichi — Calcifilaxia: tiosulfat și mortalitate la 1 an',
 'Recunoașterea tabloului cutanat necrotic, a tiosulfatului și a mortalității înalte în primul an.',
 ['Tabloul cutanat dureros/necrotic este din text.','Calcificarea plus tromboza de vase mici este caracteristica histologică.','Tiosulfatul și bifosfonații sunt citați cu succes variabil.','Decesul în primul an, amplificat de infecții, este explicit.','Warfarina inhibă carboxilarea matrix Gla, deci favorizează, nu protejează, calcificarea.']],
 8,'Mortalitatea în primul an și tiosulfatul sunt ușor de înlocuit cu un rol „protector” al warfarinei.',['Tiosulfatul de sodiu','an de la data']),

q(151,['Factori de risc cardiovascular „non-tradiționali” în uremie includ:',
 ['ADMA (dimetilarginina asimetrică), care explică în parte un risc de deces crescut cu 52% și de evenimente CV cu 34%','Inflamația care inhibă fetuina, un inhibitor hepatic al calcificărilor vasculare','Antioxidanții (vitamina E sau acetilcisteina) s-au asociat cu reducerea mortalității de orice cauză și CV','Hiperhomocisteinemia, malnutriția, stresul oxidativ și Chlamydophila pneumoniae','Acidul folic cu B6/B12 reduce constant mortalitatea, ADMA fiind protector'],'ABCD',1396,'Boala cronică de rinichi — ADMA 52%/34% și fetuina',
 'Legarea ADMA de cotele 52%/34% și a inflamației de inhibiția fetuinei, cu contrastul vitamina E versus B.',
 ['Cotele 52% și 34% legate de ADMA sunt din text.','Fetuina inhibată de inflamație este citată.','Vitamina E/acetilcisteina au asociere de mortalitate redusă.','Lista non-tradițională include homocisteina, malnutriția și Chlamydophila.','Folatul/B6/B12 s-au dovedit ineficiente; ADMA crește riscul, nu îl scade.']],
 8,'Cotele ADMA 52%/34% sunt permutabile cu SHARP; distractorul inversează rezultatul vitaminelor B.',['52%','fetuina']),

q(152,['Pericardita uremică și afectarea tegumentară din BCR:',
 ['Pericardita uremică însoțește uremia severă sau dializa ineficientă; revărsatul este adesea hemoragic, cu aritmii atriale','Anticoagulantele se folosesc cu prudență, din riscul de tamponadă; pericardita poate remite cu dializă intensivă','Porfiria cutanată tardivă din BCR ține de sinteza hepatică scăzută a decarboxilazei uroporfirinogen și de retenția porfirinelor','Amilazele serice pot crește până la de trei ori normalul fără boală pancreatică, prin retenția izoenzimei de masă mare','Pericardita uremică este o pericardită virală banală, amilaza >3× confirmând pancreatita acută la toți dializații'],'ABCD',1397,'Boala cronică de rinichi — Pericardită hemoragică, PCT și amilază ×3',
 'Deosebirea revărsatului hemoragic uremic de pancreatita „biochimică” (amilază ×3 prin retenție) și recunoașterea PCT.',
 ['Contextul uremie severă/dializă ineficientă și caracterul hemoragic sunt din text.','Prudența anticoagulantelor și remisia prin dializă intensivă sunt explicite.','Mecanismul PCT (decarboxilază + retenție) este citat.','Amilaza până la 3× fără pancreatită este explicită.','Nu este o pericardită virală banală; amilaza ×3 nu confirmă pancreatita.']],
 8,'Amilaza ×3 „fără pancreatită” și PCT prin decarboxilază sunt detalii ușor de citit ca urgențe chirurgicale.',['uroporfinogen','trei ori limita']),

q(153,['Anomalii metabolice și endocrine în BCR, dincolo de SHARP:',
 ['Necesarul de insulină la diabetic scade pe măsură ce BCR progresează, prin catabolism/excreție renală reduse și gluconeogeneză renală diminuată','În atacul de gută, AINS nefrotoxice sunt puțin utile, iar colchicina poate fi folosită; alopurinolul sau febuxostatul în doze mici previn recurențele','Hiperprolactinemia se poate manifesta cu galactoree atât la bărbați, cât și la femei','Puține femei dializate mai au ciclu menstrual; oligomenoreea/amenoreea și pierderea libidoului sunt frecvente','Necesarul de insulină crește constant, colchicina fiind contraindicată, iar galactoreea limitată la femei'],'ABCD',1397,'Boala cronică de rinichi — Insulină în scădere, colchicină, galactoree',
 'Direcția necesarului de insulină (scade), alternativa colchicinei în gută și galactoreea din hiperprolactinemie.',
 ['Scăderea necesarului de insulină și cele două mecanisme sunt din text.','Colchicina în atac și alopurinol/febuxostat la prevenție sunt explicite.','Galactoreea la ambele sexe este citată.','Amenoreea la dializate este menționată.','Direcțiile sunt inverse: insulina scade; colchicina este permisă; galactoreea nu este limitată la femei.']],
 8,'Scăderea (nu creșterea) dozei de insulină în BCR avansată este capcana de diabetologie a paginii.',['necesarul de insulină','galactoree']),

q(154,['Un pacient profund uremic este adus la prima hemodializă. Sindromul de dezechilibru de dializă:',
 ['Apare când ureea scade în sânge mai rapid decât în SNC, apa deplasându-se spre compartimentul mai bogat în uree și producând edem osmotic cerebral','Poate fi evitat prin corecția graduală, cu ședințe scurte repetate, sau prin dializă peritoneală','Uremia avansată determină polineuropatie simetrică, care poate reapare la dializă inadecvată','Este o hiponatremie de diluție din exces de dializant hipoton, fără gradient de uree trans-barieră','Se previne prin scurtarea maximală a ureei în prima oră, PD fiind contraindicată'],'ABC',1398,'Boala cronică de rinichi — Dezechilibrul de dializă: edem osmotic',
 'Mecanismul osmotic (uree-SNC) și prevenția prin ședințe scurte sau DP, plus polineuropatia uremică.',
 ['Gradientul trans-barieră de uree și edemul osmotic sunt din text.','Ședințele scurte repetate sau DP evită sindromul.','Polineuropatia simetrică, inclusiv la dializă inadecvată, este citată.','Nu este o hiponatremie de dializant hipoton.','Corecția bruscă precipită, nu previne, sindromul.']],
 8,'Direcția apei (spre SNC-ul încă uremic) este capcana osmotică a primei ședințe.',['edemul osmotic cerebral','hemodializă scurte']),

q(155,['Când RFG scade sub 20 mL/min per 1,73 m², organizarea substituției include:',
 ['O echipă dedicată pentru dietă, reevaluarea medicației, factorii de risc și sprijin în alegerea SFR sau a non-dializei','La opțiunea DP, un cateter poate fi lăsat subcutanat, retras la suprafață când începe dializa','În cazurile potrivite, pregătirea pentru transplant de la donator viu, cea mai bună metodă de SFR','FAV se creează doar după prima ședință de HD pe cateter femoral definitiv','Sub 20 mL/min se amână orice discuție până la anurie, donatorul viu fiind exclus'],'ABC',1398,'Boala cronică de rinichi — Pragul 20 mL/min și cateterul DP subcutanat',
 'Aplicarea pragului <20 mL/min pentru consiliere și a strategiei de cateter DP „îngropat”.',
 ['Pragul 20 mL/min și pachetul de consiliere sunt din text.','Cateterul lăsat subcutanat până la startul DP este explicit.','Donatorul viu este numit cea mai bună metodă de SFR.','FAV se creează din timp, nu după HD de urgență ca strategie de elecție.','Discuția nu se amână până la anurie.']],
 8,'Pragul 20 mL/min și cateterul DP îngropat sunt detalii de timing nefolosite, distincte de creatinina 400–500 a FAV.',['20 mL/min','lăsat subcutanat']),

q(156,['Medicamente de evitat sau de ajustat în BCR, dincolo de AINS și economisitoarele de K+:',
 ['Tetraciclinele, cu posibila excepție a doxiciclinei','Gentamicina și alte medicamente eliminate renal, doar în absența unei alternative, cu monitorizarea nivelului seric','Opioidele, care se pot acumula determinând „necroză opioidă”; anticoagulantele orale anti-trombină, greu de monitorizat','Tetraciclinele sunt inerte renal, doxiciclina fiind cea mai nefrotoxică','Opioidele nu se acumulează, gentamicina neavând nevoie de monitorizare'],'ABC',1398,'Boala cronică de rinichi — Tetracicline, gentamicină și opioide',
 'Recunoașterea excepției doxiciclinei și a acumulării opioidelor, alături de monitorizarea aminoglicozidelor.',
 ['Tetraciclinele de evitat, cu excepția posibilă a doxiciclinei, sunt din text.','Gentamicina cu monitorizare, doar fără alternativă, este explicită.','Acumularea opioidelor și dificultatea anti-trombinelor orale sunt citate.','Relația este inversă: doxiciclina este excepția mai sigură.','Opioidele se acumulează; gentamicina cere monitorizare.']],
 8,'Excepția doxiciclinei și „necroza opioidă” sunt detalii de prescripție ușor de inversat.',['doxiciclinei','opioidele']),

q(157,['Conform Cadranului 36.37, intervalul uzual al bicarbonatului în dializantul de hemodializă este:',
 ['0–4 mmol/L, identic potasiului','5–8 mmHg, identic presiunii portale','77–236 mmol/L, identic glucozei din DP','1,0–1,6 mmol/L, identic calciului','35–40 mmol/L'],'E',1399,'Boala cronică de rinichi — Cadranul 36.37: bicarbonatul dializantului',
 'Reținerea ferestrei 35–40 mmol/L a bicarbonatului, distinctă de K, Ca sau glucoza DP.',
 ['0-4 mmol/L este intervalul potasiului, nu al bicarbonatului.','5-8 mmHg este presiunea portală, nu o concentrație de dializant.','77-236 mmol/L este glucoza din DP.','1,0-1,6 mmol/L este calciul din dializantul HD.','Cadranul indică bicarbonat 35-40 mmol/L.']],
 8,'Permutează 35–40 (bicarbonat HD) cu 0–4 (K) și 77–236 (glucoză DP), trei intervale din cadrane învecinate.',['35-40','Bicarbonat']),

q(158,['Când FAV nu este disponibilă imediat, abordul pentru hemodializă și țintele de ședință includ:',
 ['Cateterul venos central tunelizat, cu lumen dublu, pe jugulară sau femurală, asociat cu bacteriemie, tromboză sau stenoză venoasă','Pentru urgență, un cateter temporar netunelizat, de calibru mare, pe subclavie, jugulară sau femurală','Un dializant cu K 1–3 mmol/L permite un bilanț negativ de 1–2 mmol/kg pe ședință','Sodiul dializantului, de obicei 137–141 mmol/L, se individualizează pentru a evita schimburi mari de apă','Cateterul tunelizat înlocuiește FAV ca abord definitiv de elecție, fără risc de bacteriemie'],'ABCD',1400,'Boala cronică de rinichi — Cateter tunelizat versus țintele de K și Na',
 'Deosebirea cateterului tunelizat (riscuri) de FAV și reținerea bilanțului de K 1–2 mmol/kg cu Na 137–141.',
 ['Tunelizarea pe jugulară/femurală și complicațiile sunt din text.','Cateterul temporar netunelizat de urgență este explicit.','K 1-3 mmol/L cu bilanț negativ 1-2 mmol/kg este citat.','Na 137-141 mmol/L este fereastra uzuală.','FAV rămâne abordul de elecție; cateterul are risc semnificativ de bacteriemie.']],
 8,'Bilanțul de K 1–2 mmol/kg și Na 137–141 sunt ușor de permutat; distractorul promovează cateterul ca elecție.',['1-2 mmol/kg','137-141 mmol/L']),

q(159,['Hemofiltrarea, distinctă de hemodializă, se caracterizează prin:',
 ['Absența dializantului; plasma este eliminată prin convecție pe o membrană high-flux, apoi înlocuită cu lichid de substituție','Poate fi preferată la pacientul instabil hemodinamic, mai ales în terapie intensivă','HDF cu convecție mare urmărește moleculele medii (ex. β2-microglobulina 11,8 kDa) și prevenția amiloidozei de dializă','Dializantul în contracurent rămâne indispensabil, convecția fiind abandonată la tinerii hiperimunizați','β2-microglobulina este albumină de 66 kDa, hemofiltrarea neavând rol în amiloidoză'],'ABC',1400,'Boala cronică de rinichi — Hemofiltrare: convecție fără dializant',
 'Contrastul convecție-fără-dializant versus HD prin difuziune și ținta β2-microglobulinei 11,8 kDa.',
 ['Absența dializantului și substituția după convecție definesc hemofiltrarea.','Preferința la instabilul de ATI este citată.','HDF pentru molecule medii și prevenția amiloidozei, mai ales la tinerii netransplantabili, este din text.','Hemofiltrarea tocmai evită dializantul.','Masa 11,8 kDa este a β2-microglobulinei, nu a albuminei.']],
 8,'Absența dializantului este definiția ușor de ratat; 11,8 kDa distinge β2-microglobulina de albumină.',['high-flux','11,8 kDa']),

q(160,['Dializa peritoneală (Cadranul 36.38 și cateterul Tenckhoff):',
 ['Cateterul flexibil este tunelizat subcutanat, cu vârful în pelvis','Potasiul din dializantul uzual este 0 mmol/L, lactatul 35–40 mmol/L, osmolaritatea totală 356–511 mOsm/kg','Glucoza 77–236 mmol/L (adesea exprimată g/dL anhidră, ex. 1,36% = 77 mmol/L) determină ultrafiltrarea osmotică','Un dializant mai hiperton (6,36%) este disponibil pentru DP acută intermitentă','Potasiul dializantului este 4 mmol/L, osmolaritatea 35–40 mOsm/kg, vârful cateterului rămânând subcutanat'],'ABCD',1401,'Boala cronică de rinichi — DP: K zero, 1,36% = 77 mmol/L, Tenckhoff',
 'Reținerea K=0, a conversiei 1,36%→77 mmol/L și a poziției pelvine a Tenckhoff.',
 ['Tunelul subcutanat cu vârf pelvin este din figură/text.','K 0, lactat 35-40 și 356-511 mOsm/kg sunt din cadran.','Conversia 1,36% = 77 mmol/L este nota cadranului.','6,36% pentru DP acută este menționat.','K nu este 4; osmolaritatea nu este 35-40 (aceasta e lactatul); vârful este în pelvis.']],
 8,'Conversia 1,36% = 77 mmol/L și K=0 sunt capcane numerice pe cadranul de DP.',['1,36% = 77 mmol/L','356-511 mOsm/kg']),

q(161,['Dializa la pacientul debilitat și câștigurile transplantului reușit:',
 ['Într-un studiu, circa 50% dintre pacienți au decedat în primul an de dializă, iar circa 30% au avut declin al statusului funcțional','Transplantul corectează anemia și infertilitatea și scade necesitatea de paratiroidectomie','Capacitatea donatorilor în Marea Britanie este 44/milion populație pe an, depășită de cerere','Mortalitatea în primul an este sub 2%, paratiroidectomia crescând după transplant','Donatorii sunt 44.000/milion, cererea fiind acoperită, anemia persistând post-grefă'],'ABC',1402,'Boala cronică de rinichi — Debilitați: 50%/30% și donatori 44/milion',
 'Contrastul prognosticului nefavorabil al dializei la fragili (50% deces/an 1) cu corectarea anemiei/infertilității prin grefă.',
 ['Cifrele 50% deces și 30% declin funcțional sunt din text.','Corectarea anemiei, infertilității și scăderea paratiroidectomiei sunt explicite.','44/milion și depășirea cererii sunt citate.','Mortalitatea citată este ~50% în anul 1, nu 2%; paratiroidectomia scade.','44, nu 44.000, pe milion; anemia se corectează.']],
 8,'Permutează 50% (mortalitate an 1) cu 44 (donatori/milion), două ordine de mărime de pe aceeași pagină.',['44/milion','50% dintre']),

q(162,['Imunosupresia de transplant (Cadranul 36.40) și donatorul viu feminin:',
 ['Belataceptul (anti-B7) previne implicarea B7–CD28; eculizumabul blochează C5 activat','Basiliximabul și daclizumabul blochează receptorul IL-2, ca tratament de inducție','Alemtuzumabul (anti-CD52) distruge limfocitele B și T','Femeile care donează rinichi au risc mai mare de hipertensiune gestațională sau preeclampsie la sarcinile ulterioare, fără riscuri pentru copii','Belataceptul este un analog de vitamină D, iar donarea feminină anulează riscul obstetrical'],'ABCD',1403,'Boala cronică de rinichi — Belatacept, eculizumab și donatoarea gravidă',
 'Maparea țintelor B7/C5/IL-2/CD52 și avertismentul obstetrical pentru donatoare.',
 ['Belatacept și eculizumab sunt din cadran, cu țintele B7-CD28 și C5.','Anti-CD25 (basiliximab/daclizumab) blochează IL-2.','Alemtuzumabul anti-CD52 distruge B și T.','Riscul de HTA gestațională/preeclampsie, fără risc pentru copil, este explicit.','Belataceptul nu este vitamină D; riscul obstetrical există.']],
 8,'Trei anticorpi (B7, C5, CD52) sunt concepuți să fie amestecați; riscul de preeclampsie al donatoarei este detaliul nefolosit.',['Belatacept','preeclampsie']),

q(163,['Infecțiile după transplantul renal, dincolo de fereastra bacteriană <1 lună:',
 ['CMV apare în săptămâni–luni la 70% dintre primitorii seronegativi cu donator pozitiv, fără profilaxie cu valganciclovir, și după agenți biologici','Profilaxia cu cotrimoxazol în primele luni este necesară pentru Pneumocystis jirovecii','Nefropatia BK (polyomavirus) produce o NTI adesea agresivă; unica terapie este reducerea imunosupresiei','Rinichii transportați pe aparat de perfuzie cu hipotermie controlată s-au asociat cu ameliorarea DGF','CMV este excepțional sub 5% fără profilaxie, BK tratându-se prin creșterea calcineurinicului'],'ABCD',1404,'Boala cronică de rinichi — CMV 70%, PCP și BK',
 'Reținerea cotei CMV 70% D+/R−, a cotrimoxazolului anti-PCP și a reducerii (nu creșterii) IS în BK.',
 ['70% D+/R− fără valganciclovir este din text.','Cotrimoxazolul anti-PCP în primele luni este explicit.','BK se gestionează prin reducerea imunosupresiei.','Perfuzia hipotermică ameliorând DGF este citată.','Cota CMV nu este <5%; calcineurinicul crescut agravează, nu tratează, BK.']],
 8,'Cota 70% D+/R− și reducerea IS în BK sunt ușor de inversat spre „crește calcineurinicul, CMV e rar”.',['ganciclovir','Polyomavirus']),

q(164,['Complicațiile tardive ale grefei, dincolo de PTLD/EBV și de decesul CV 50%:',
 ['GSFS primară reapare frecvent și duce la pierderea precoce a grefei; reapar și GNMC, nefropatia diabetică și nefropatia cu IgA','Fibroza interstițială cu atrofie tubulară, numită anterior nefropatie cronică de allogrefă, este un aspect histologic frecvent','Declinul progresiv se asociază cu proteinurie ușoară-moderată (<3 g/zi); intervențiile nu s-au dovedit încă benefice','Imunosupresia crește riscul tumorilor cutanate, inclusiv carcinoame bazocelulare și spinocelulare','GSFS nu recidivează pe grefă, proteinuria >10 g/zi fiind necesară diagnosticului de IFTA'],'ABCD',1404,'Boala cronică de rinichi — Recurențe pe grefă și IFTA',
 'Recunoașterea recurenței GSFS/GNMC/DZ/IgA, a IFTA (fostă nefropatie cronică de allogrefă) și a pragului <3 g/zi.',
 ['Lista de recurențe, cu GSFS ca pierdere precoce, este din text.','IFTA ca termen actual pentru fosta nefropatie cronică de allogrefă este explicită.','Proteinuria <3 g/zi și absența unei intervenții dovedite sunt citate.','BCC și SCC sunt menționate.','GSFS recidivează; pragul de proteinurie al declinului este <3 g/zi, nu >10.']],
 8,'Recurența precoce a GSFS și redenumirea IFTA sunt detalii ușor de negat; <3 g/zi distinge de nefrotic.',['<3 g/zi','allogrefă']),
];
